import {
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
  Group,
  Vector3,
} from 'three/webgpu';
import { gsap } from 'gsap';
import { createTextNode } from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // Plane for brushed metal background
  const width = 1.5;
  const height = 0.3;
  const geometry = new PlaneGeometry(width, height);
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  const material = new MeshBasicNodeMaterial({
    map: texture,
  });
  const plane = new Mesh(geometry, material);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // Text label "Journal 1"
  const text = createTextNode({
    text: 'Journal 1',
    font: 'Lora',
    weight: 400,
    size: 0.13, // body size in scene units (matches spec body 0.13, but spec says 39px? we'll map 39px to ~0.13 scene units)
    color: config.colors.paper,
    atlas: ctx.fontAtlas,
  });
  text.position.set(0, 0, 0.01); // slight offset above plane
  text.scale.set(1, 1, 1);
  group.add(text);

  // Apply scene placement
  group.position.copy(new Vector3(config.scenePosition.x, config.scenePosition.y, config.scenePosition.z));
  group.rotation.set(
    config.scenePosition.rotation?.x || 0,
    config.scenePosition.rotation?.y || 0,
    config.scenePosition.rotation?.z || 0
  );
  group.scale.copy(new Vector3(
    config.scenePosition.scale?.x || 1,
    config.scenePosition.scale?.y || 1,
    config.scenePosition.scale?.z || 1
  ));

  // Event handlers (none)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    if (text.dispose) text.dispose(); // assume text node has dispose
    // No GSAP timelines to kill
  };

  return group;
}
